add_filter( 'woocommerce_package_rates', 'perfectpixel_hide_rates_by_user_role', 20 );

function perfectpixel_hide_rates_by_user_role( $rates ) {
	$user  = wp_get_current_user();
	$roles = array_filter( array_map( 'trim', explode( ',', '{{hidden_rates_roles}}' ) ) );
	if ( ! $user->exists() || ! array_intersect( $roles, (array) $user->roles ) ) {
		return $rates;
	}
	$hide = array_filter( array_map( 'trim', explode( ',', '{{hidden_rates_ids}}' ) ) );
	foreach ( $rates as $key => $rate ) {
		if ( in_array( $key, $hide, true ) || in_array( $rate->get_method_id(), $hide, true ) ) {
			unset( $rates[ $key ] );
		}
	}
	return $rates;
}
